for loc, T, fn in (("vi", VI, "lite.html"), ("en", EN, "lite-en.html"), ("ja", JA, "lite-ja.html")):
    full = {"vi": "index.html", "en": "en.html", "ja": "ja.html"}[loc]
    nav = [("#intro", T["sections"][0]["title"].split(". ", 1)[1]), ("#install", T["sections"][4]["title"].split(". ", 1)[1]), ("#admin", T["sections"][7]["title"].split(". ", 1)[1]), ("#trouble", T["sections"][9]["title"].split(". ", 1)[1]), (full, T["nav_full"])]
    with open(os.path.join(OUT, fn), "w", encoding="utf-8") as f:
        f.write(render(loc, T, "lite/" + loc, LANGS, nav))
    print("wrote", fn)
